/**
 * Hand-authored content for /guides and /guides/<slug>.
 *
 * Unlike spec-data.ts (generated from core/), there is no canonical source
 * for this content elsewhere in the monorepo: it lives here. Adding a new
 * guide is one new object appended to `guideEntries`; no new .vue file, no
 * manual route/sitemap/llms edit (all three are derived from this file, see
 * nuxt.config.ts, scripts/gen-sitemap.ts, scripts/gen-llms.ts).
 *
 * `text` fields may contain inline <code>/<strong>/<a>: rendered with
 * v-html in GuideBody.vue, same convention spec pages use for prose.
 */

export type GuideCategory = 'vs' | 'practice' | 'concepts'

export type GuideBlock =
  | { type: 'p'; text: string }
  | { type: 'h2'; text: string }
  | { type: 'list'; items: string[] }
  | { type: 'code'; lang: string; code: string; label?: string }
  | { type: 'callout'; tone: 'do' | 'dont'; text: string }
  | { type: 'table'; head: string[]; rows: string[][] }

