export const guideSlugs = guideEntries.map(g => g.slug)

export function getGuideEntry(slug: string): GuideEntry | undefined {
  return guideEntries.find(g => g.slug === slug)
}

export const guideGroups = (['concepts', 'vs', 'practice'] as GuideCategory[]).map(category => ({
  category,
  label: guideCategoryLabels[category],
  items: guideEntries.filter(g => g.category === category)
}))
